    new_lines=[]
    for line in lines:
        m=re.match(r'(?P<var>\w+):\s*(?P<type>\w+(?:\[[^\]]+\])?)\s*=\s*(?P<value>.+?)\s*#', line)
        if m and '# MYPY_ERROR' in line:
            t=m.group('type')
            val=m.group('value')
            # decide
            if t=='int':
                val='0'
            elif t=='bool':
                val='True'
            elif t=='str':
                val='""'
            elif t=='float':
                val='0.0'
            elif t=='list[int]':
                val='["x"]'
            elif t=='dict[str,int]':
                val='{"x":1}'
            line=f"{m.group('var')}:{t} = {val}"
        new_lines.append(line)
    p.write_text('\n'.join(new_lines))
